THOUGHT: The change looks correct. Now let me create a simple test to verify that our fix works. I'll create a test that simulates the scenario where a segment has both corrupted and valid records.

```bash
cat <<'EOF' > recovery_fix_test.go
package pogreb

import (
	"path/filepath"
	"testing"

	"github.com/akrylysov/pogreb/internal/assert"
	"github.com/akrylysov/pogreb/fs"
)

func TestRecoveryWithCorruptedAndValidRecords(t *testing.T) {
	segPath := filepath.Join(testDBName, segmentName(0, 1))
	opts := &Options{FileSystem: testFS}

	// Create a test database
	db, err := createTestDB(opts)
	assert.Nil(t, err)

	// Add some valid records
	for i := byte(0); i < 5; i++ {
		assert.Nil(t, db.Put([]byte{i}, []byte{i}))
	}

	assert.Equal(t, uint32(5), db.Count())
	assert.Nil(t, db.Close())

	// Simulate crash by creating a lock file
	assert.Nil(t, touchFile(testFS, filepath.Join(testDBName, lockName)))

	// Add a corrupted record followed by valid records to segment file
	// This simulates the edge case that was failing before the fix
	corruptedData := []byte{1, 0, 1, 0, 0, 0, 1 /* incomplete record */}
	validData := []byte{1, 0, 1, 0, 0, 0, 2, 2, 252, 15, 236, 190} // Valid record

	// Append corrupted data
	assert.Nil(t, appendFile(segPath, corruptedData))

	// Append valid data after corrupted data
	assert.Nil(t, appendFile(segPath, validData))

	// Try to reopen the database - this should trigger recovery
	db, err = Open(testDBName, opts)
	assert.Nil(t, err)

	// Check that we still have our original 5 records plus the new valid record
	// The corrupted record should be truncated and ignored
	assert.Equal(t, uint32(6), db.Count())

	// Verify all expected records exist
	for i := byte(0); i < 5; i++ {
		v, err := db.Get([]byte{i})
		assert.Nil(t, err)
		assert.Equal(t, []byte{i}, v)
	}

	// Check the record added after the corrupted one
	v, err := db.Get([]byte{2})
	assert.Nil(t, err)
	assert.Equal(t, []byte{2}, v)

	assert.Nil(t, db.Close())
}
EOF
```

